input.command:
mkdir -p .lawcheck/rules && cat > .lawcheck/rules/no-fetch.mjs <<'EOF'
export async function check({ files: [file] }) {
  const { root } = await file.tree();
  if (root === null) return [];
  const findings = [];
  const stack = [root];
  while (stack.length > 0) {
    const node = stack.pop();
    const callee = node.type === 'call_expression' ? node.children.find((child) => child.field === 'function') : undefined;
    if (callee && file.text.slice(callee.start, callee.end) === 'fetch') findings.push({ line: node.line, message: 'calls fetch outside the api layer' });
    stack.push(...node.children);
  }
  return findings;
}
EOF
python3 - <<'EOF'
p='.lawcheck/law.yaml'
s=open(p).read()
s=s.replace("types:\n","rules:\n  no-fetch:\n    why: Only the api layer talks to the network.\n\ntypes:\n",1)
s=s.replace("may_use: [core]","may_use: [core]\n    rules: [no-fetch]")
open(p,'w').write(s)
EOF
cat .lawcheck/law.yaml; lawcheck try no-fetch; lawcheck check --full

